# content_lcad.py: part of the manuscript build for the analysis of lung cancer deaths relative to treated persons (see README).
from numbers_lcad import load, ROB, RS, SENS, SIDO_EN, EDU, OUTC, CSR
import os, pandas as pd
N = load()
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f} to {t[2]:.3f}"
def ci(v): r = N["main"][v]; return tci((r["IRR"], r["lo"], r["hi"]))
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
NCO = lambda o, v: N["nco"][(o, v)]
SC = lambda s, v: N["sens_main"][s][v]
BW = lambda v, part: N["bw"][f"{v}__{part}"]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
GHP, SMK, TB, COAL, FAC_L, DET, WALK, MPA, FAC, BLS = ("ext__genhosp_per100k", "current_smoking_rate", "prior_tb_share", "coal_plant_host", "factory_land_share",
    "detached_house_households", "walking_practice_rate", "moderate_pa_rate", "public_sports_facilities_per_100k", "basic_livelihood_rate")
TITLE = "Where do lung cancer deaths exceed the volume of lung cancer care in Korea?"
RUNNING = "Lung cancer deaths per treated patient"
KEYWORDS = "lung neoplasms; mortality; health services accessibility; small-area analysis; Republic of Korea"
_kw = [k.strip() for k in KEYWORDS.split(";")]
assert ":" not in TITLE and not any(c.isupper() for w in TITLE.split()[1:] for c in w[1:]) and len(RUNNING) < 40 and 3 <= len(_kw) <= 5
assert N["family"] == "poisson" and N["waic_pois"] < N["waic_nb"]
NHYP = N["n_hyp"]; assert NHYP == 13
SUP = {"methods": "Supplemental Data 1, Supplementary Methods", "covariates": "Supplemental Data 1, Table S1", "specs": "Supplemental Data 1, Table S2",
       "prespec": "Supplemental Data 1, Table S3", "persistence": "Supplemental Data 1, Figure S1",
       "region": "Supplemental Data 1, Table S4", "resid": "Supplemental Data 1, Table S5", "parsim": "Supplemental Data 1, Table S6"}
def sup(k): return SUP[k]
WN = ("W1_2011-15", "W2_2016-19", "W3_2020-24")
D = N["dist"]; HB = N["hot_by_sido"]; CB = N["cold_by_sido"]; NS = N["n_sido"]; HS = N["sens_hot"]
EN = lambda r: {"경상남도함안군": "Haman", "강원도원주시": "Wonju", "경상북도안동시": "Andong", "충청남도금산군": "Geumsan", "전라남도화순군": "Hwasun", "서울시서초구": "Seocho-gu, Seoul",
                "강원도태백시": "Taebaek"}[r]
AI_METHODS = "The author used Claude (Anthropic) and ChatGPT (OpenAI) only for translation and English-language editing of the manuscript."
NUMW = {12: "twelve", 13: "thirteen"}
LO = lambda s, v: N["leaveout"][(s, v)]

METHODS = [
("Data and outcome",
 f"This ecological study used deaths with lung cancer (International Classification of Diseases, 10th revision, C33-C34) as the underlying cause in 2011-2024 by district of residence from the national cause-of-death statistics, which cover all registered deaths [@web:kostat2026cause], and the number of persons treated for lung cancer (C33-C34) by district of residence from the regional claims statistics of the National Health Insurance Service [@web:nhis2026regional]. Each person with at least one claim for the disease in a year is counted once in that year, so the count is prevalent: it includes newly diagnosed patients, patients in continuing treatment and survivors under follow-up. Districts were harmonized to {N['n_districts']} units with 2024 boundaries ({N['n_rows']:,} district-years), with resident populations by sex and 5-year age group as denominators [@web:mois2026population]. All data were joined by district code ({sup('methods')})."),
("Mortality relative to treatment",
 "Expected deaths were obtained by indirect standardization: national sex- and age-specific lung cancer death rates in seventeen 5-year age groups and an open-ended group aged 85 years or older were applied to each district's population each year [@inskip1983methods]. Expected treated persons were obtained in the same way from national age-specific treatment rates in ten age groups, the oldest 75 years or older, because treated persons were not published by sex. Both expectations were rescaled each year to the national observed total. The treatment ratio (observed over expected treated persons) indexes the age-standardized volume of lung cancer care in a district, which reflects incidence, detection, survival and continuing care. The offset was log(expected deaths × treatment ratio), with the product rescaled each year so that it summed to the national observed deaths, so that district effects and rate ratios refer to the age-standardized ratio of deaths to treated persons relative to the national ratio (mortality-to-treatment ratio). The ratio is related to, but distinct from, the mortality-to-incidence ratio and does not estimate survival [@ellis2019mir]. Lung cancer mortality was one of several candidate outcomes screened for spatial structure, and the ratio to treated persons was then defined as the outcome; the analysis is therefore exploratory."),
("District characteristics",
 f"Thirteen district characteristics were chosen from the literature on lung cancer outcomes and access to care [@forrest2013treatment; @kim2026regional; @eckel2016air; @jeong2024income]: general hospitals per 100,000 residents, the out-of-district outpatient share (residents treated as outpatients outside the district over those treated inside or outside it, all conditions) and uptake of the national cancer screening program for care access and detection; current smoking; coal-fired power plants in the district, the share of land used by factories and the share of households in detached houses (an indicator of indoor radon [@kim2018radon]) for air and residential exposure; previous pulmonary tuberculosis at national health screening; walking, moderate-to-vigorous physical activity and public sports facilities per 100,000 residents for activity; and the shares of basic livelihood security recipients and of adults with tertiary education for socioeconomic position. Smoking and activity were age-standardized district estimates from the Community Health Survey. The urban population share, physicians per 1,000 residents, the sex ratio, fiscal autonomy and the share aged 80 years or older were forced into every model. Missing covariate cells were interpolated within districts or filled with district or yearly means; definitions, sources and filled cells are listed in {sup('covariates')}. Covariates were standardized to mean 0 and standard deviation (SD) 1. The hit-and-run share of traffic crashes, a traffic culture index and fires per 10,000 residents served as negative-control exposures [@lipsitch2010negative]."),
("Statistical analysis",
 f"A Poisson likelihood was chosen over negative binomial by the lower widely applicable information criterion (WAIC) of the forced-controls model ({N['waic_pois']:,.1f} vs {N['waic_nb']:,.1f}). Models had a Besag-York-Mollié 2 (BYM2) district effect with penalized-complexity priors [@besag1991bayesian; @riebler2016intuitive; @simpson2017penalising], random-walk and independent year effects with penalized-complexity priors and normal priors on fixed effects (mean 0, precision 4), fitted by integrated nested Laplace approximation [@rue2009approximate] in R [@web:rcore2026]. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. Intervals were not adjusted for multiplicity; with thirteen characteristics, about 0.65 credible associations would be expected by chance alone. Credible intervals and subset stability are not multiplicity-controlled evidence. Residual hot and cold spots were districts of the principal model with a posterior probability above 0.95 or below 0.05 that the residual spatial RR exceeded 1, reported descriptively without adjustment for the number of districts, together with the number whose residual RR was 1.10 or more (hot) or 0.90 or less (cold). A characteristic was subset-stable when its interval excluded 1 in at least 75% of 200 random covariate subsets containing it, with at least 95% sign agreement. Robustness was examined with Knorr-Held type I-IV space-time interactions [@knorrheld2000bayesian], alternative neighborhood graphs, likelihoods and year effects, lags, calendar windows, leave-one-province and leave-one-year-out refits, 20 perturbations of filled values, between- and within-district decomposition [@bell2015explaining], region-specific slopes, E-values [@vanderweele2017sensitivity] and two comparison outcomes without a lung cancer pathway, deaths from transport accidents and falls ({sup('specs')}). Five sensitivity analyses were specified: deaths without the treatment adjustment (mortality level), a 3-year moving-average treatment ratio, a queen-contiguity graph, removal of the forced share aged 80 years or older and expected deaths from the ten age groups used for treated persons, without sex ({sup('prespec')})."),
("Ethics and reporting",
 "The study used only published aggregate statistics. The Institutional Review Board of Hongik University approved the study (7002340-202511-HR-012; continuing review 7002340-202611-HR-040) and waived informed consent. Reporting follows the Strengthening the Reporting of Observational Studies in Epidemiology (STROBE) statement [@vonelm2007strengthening] (Supplemental Data 1)."),
]

_R5 = lambda v: tci(SC("smr", v))
RESULTS = [
("Deaths, treatment and their ratio",
 f"Over 2011-2024, {N['cases_total']:,} lung cancer deaths occurred in {N['py']/1e6:.0f} million person-years (Table 1). The directly age-standardized death rate (2015 population) fell from {N['asr_2011']:.1f} per 100,000 in 2011 to {N['asr_2024']:.1f} in 2024, while persons treated rose from {N['care_2011']:,} to {N['care_2024']:,}; deaths per 100 treated persons fell from {N['ratio_2011']:.1f} to {N['ratio_2024']:.1f} (Figure 1D). Over the whole period the 10th-90th percentile range across districts was {D['smr'][0]:.2f}-{D['smr'][2]:.2f} for the standardized mortality ratio (SMR), {D['sir_care'][0]:.2f}-{D['sir_care'][2]:.2f} for the treatment ratio and {D['mtr'][0]:.2f}-{D['mtr'][2]:.2f} for the mortality-to-treatment ratio, which ranged from {N['mtr_min'][1]:.2f} in {EN(N['mtr_min'][0])} to {N['mtr_max'][1]:.2f} in {EN(N['mtr_max'][0])}. District SMRs were weakly correlated with treatment ratios (Spearman's rho {N['rho_smr_care']:.2f}), and mortality-to-treatment ratios were correlated positively with SMRs (rho {N['rho_mtr_smr']:.2f}) and negatively with treatment ratios (rho {N['rho_mtr_care']:.2f}) (Figure 1A-C)."),
("Geography",
 f"Moran's I of the pooled observed log mortality-to-treatment ratio was {N['moran_pooled']:.2f}, annual values were {N['moran_year_min']:.2f}-{N['moran_year_max']:.2f} (all P < 0.05) and the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f} to {N['phi'][2]:.2f}). After adjustment, {N['n_hot']} districts were residual hot spots, including {HB['38']} of {NS['38']} districts in South Gyeongsang, {HB['21']} of {NS['21']} in Busan, {HB['37']} of {NS['37']} in North Gyeongsang, {HB['32']} of {NS['32']} in Gangwon, {HB['33']} in North Chungcheong and {HB['22']} in Daegu, and {N['n_cold']} were cold spots, {CB['36']} in South Jeolla, {CB['11']} in Seoul and {CB['31']} in Gyeonggi (Figure 1C); {N['n_hot_rr110']} hot spots had a residual RR of 1.10 or more and {N['n_cold_rr090']} cold spots an RR of 0.90 or less. Residual RRs ranged from {N['cold_top'][0][1]:.2f} in {EN(N['cold_top'][0][0])} to {N['hot_top'][0][1]:.2f} in {EN(N['hot_top'][0][0])}. In the model of mortality without the treatment adjustment there were {HS['smr']['n_hot']} hot spots, {HS['smr']['overlap']} of them shared with the principal model; none was in Busan, where {HS['smr']['busan_cold']} districts were cold spots. {NUMW[N['hot_all_windows']].capitalize()} hot spots and {NUMW[N['cold_all_windows']]} cold spots recurred in all three calendar windows, the Spearman correlation of residual RRs between 2011-2015 and 2020-2024 was {N['win_rr_rho']:.2f}, and Kendall's W of annual rankings was {N['kendall_W']:.2f} ({sup('persistence')})."),
("District characteristics",
 f"Adding the {NHYP} characteristics lowered WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f}. Two characteristics were credibly associated (Table 2): the ratio was higher with a larger out-of-district outpatient share ({ci(OUTC)}) and lower with a larger share of adults with tertiary education ({ci(EDU)}). Cancer screening uptake ({ci(CSR)}), current smoking ({ci(SMK)}), coal-fired power plants ({ci(COAL)}), factory land, detached housing ({ci(DET)}), previous tuberculosis, general hospitals, the three activity indicators and basic livelihood recipients ({ci(BLS)}) were not credibly associated. Among the forced controls, the ratio was higher with a larger urban population share ({ci('urban_population_share')}), share aged 80 years or older ({ci('pop80_share')}) and sex ratio ({ci('sex_ratio')}) and lower with greater fiscal autonomy ({ci('fiscal_independence')}). Of the negative-control exposures, the traffic culture index was credibly associated ({tci((N['negctl']['traffic_culture_index']['IRR'], N['negctl']['traffic_culture_index']['lo'], N['negctl']['traffic_culture_index']['hi']))}) and the other two were not."),
("Robustness",
 f"The out-of-district outpatient share was subset-stable ({100*N['mv'][OUTC]['cred_frac']:.0f}% of subsets), credible in all four space-time interaction models ({tci(S43('KH_typeIV', OUTC))} in type IV, which had the lowest WAIC), in {N['retention'][OUTC]['kept']} of {N['retention'][OUTC]['n_specs']} alternative fits, in all 20 perturbations and in {LO('province', OUTC)[1]} of {LO('province', OUTC)[0]} leave-one-province and {LO('year', OUTC)[1]} of {LO('year', OUTC)[0]} leave-one-year-out refits (Figure 2; {sup('specs')}). Its within-district component was credible ({tci(BW(OUTC, 'within'))}) and its between-district component was not ({tci(BW(OUTC, 'between'))}). With region-specific slopes, the interval excluded 1 only in the capital region ({tci(N['s50_region'][(OUTC, 'Capital')])}; {sup('region')}). For mortality without the treatment adjustment the estimate was {_R5(OUTC)}, and for the comparison outcomes it was {tci(NCO('FALL', OUTC))} for falls and {tci(NCO('TRANS', OUTC))} for transport accidents. E-values were {N['evalue'][OUTC]['E_point']:.2f} for the estimate and {N['evalue'][OUTC]['E_limit']:.2f} for the interval limit. "
 f"Tertiary education was credible in all subsets, all space-time interaction models, all {N['retention'][EDU]['n_specs']} alternative fits, all leave-one-out refits, both the between-district ({tci(BW(EDU, 'between'))}) and within-district ({tci(BW(EDU, 'within'))}) components and for mortality without the treatment adjustment ({_R5(EDU)}); it was also associated with deaths from falls ({tci(NCO('FALL', EDU))}) and transport accidents ({tci(NCO('TRANS', EDU))}). Cancer screening uptake was credible in {100*N['mv'][CSR]['cred_frac']:.0f}% of subsets but in none of the space-time interaction models."),
(None, "SENS_PLACEHOLDER"),
]

def _sens_sentence():
    e = {v: SC(v, OUTC) for v in SENS}; t = {v: SC(v, EDU) for v in SENS}
    return (f"In the five sensitivity analyses, the out-of-district outpatient share remained credible with the 3-year treatment ratio ({tci(e['ma3'])}), the queen graph ({tci(e['s577'])}), without the forced share aged 80 years or older ({tci(e['s2'])}) "
            f"and with expected deaths from ten age groups ({tci(e['s8'])}), and tertiary education remained credible in all five ({sup('prespec')}). Hot spots numbered {HS['ma3']['n_hot']}, {HS['s577']['n_hot']}, {HS['s2']['n_hot']} and {HS['s8']['n_hot']} in these four analyses "
            f"(Jaccard similarity with the principal hot spots {min(HS[v]['jac'] for v in ('ma3', 's577', 's2', 's8')):.2f} or higher). ")
_tail = (f"Residual Moran's I was {N['moran_resid']:.3f} (P = {N['moran_resid_p']:.2f}; {sup('resid')}), and a parsimonious model with the three subset-stable characteristics gave similar estimates for the out-of-district outpatient share and tertiary education ({sup('parsim')}). Posterior predictive 95% intervals covered {100*N['ppc']['coverage95']:.1f}% of district-years, and with district deaths in 2024 withheld (conditional on national 2024 totals), 95% predictive intervals covered {100*N['oos']['coverage95']:.1f}% of districts.")
RESULTS[4] = (None, _sens_sentence() + _tail)

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
H = [v for v in M if M[v]["role"] == "hypothesis"]
assert {v for v in H if M[v]["cred"]} == {OUTC, EDU} and M[OUTC]["IRR"] > 1 and M[EDU]["IRR"] < 1 and N["waic_main"] < N["waic_forced"]
assert all(S43(a, OUTC)[3] for a in KH) and not any(S43(a, CSR)[3] for a in KH) and all(S43(a, EDU)[3] for a in KH) and min(KH, key=lambda a: N["s43_waic"][a]) == "KH_typeIV"
assert N["rubin"][OUTC]["n_cred"] == 20 and N["rubin"][EDU]["n_cred"] == 20 and N["mv"][EDU]["cred_frac"] == 1 and N["retention"][EDU]["kept"] == N["retention"][EDU]["n_specs"]
assert LO("province", EDU)[0] == LO("province", EDU)[1] and LO("year", EDU)[0] == LO("year", EDU)[1]
assert BW(OUTC, "within")[3] and not BW(OUTC, "between")[3] and BW(EDU, "within")[3] and BW(EDU, "between")[3]
assert N["s50_region"][(OUTC, "Capital")][3] and not any(N["s50_region"][(OUTC, r)][3] for r in ("Yeongnam", "Honam", "Chungcheong", "Gangwon_Jeju"))
assert not SC("smr", OUTC)[3] and SC("smr", EDU)[3] and all(SC(v, OUTC)[3] for v in ("ma3", "s577", "s2", "s8")) and all(SC(v, EDU)[3] for v in SENS)
assert NCO("FALL", OUTC)[3] and NCO("FALL", OUTC)[0] > 1 and NCO("TRANS", OUTC)[3] and NCO("TRANS", OUTC)[0] < 1 and NCO("FALL", EDU)[3] and NCO("TRANS", EDU)[3]
assert N["negctl"]["traffic_culture_index"]["cred"] and not N["negctl"]["hit_and_run_rate"]["cred"] and not N["negctl"]["fires_per_10000"]["cred"]
assert all(M[c]["cred"] for c in ("urban_population_share", "pop80_share", "sex_ratio", "fiscal_independence")) and M["urban_population_share"]["IRR"] > 1 and M["sex_ratio"]["IRR"] > 1 and M["fiscal_independence"]["IRR"] < 1
assert N["moran_year_p_max"] < 0.05 and HS["smr"]["busan_cold"] > 0 and not HS["smr"]["hot_sido"].get("Busan") and N["rho_mtr_care"] < -0.3 and N["rho_mtr_smr"] > 0.5 and abs(N["rho_smr_care"]) < 0.3
assert SC("smr", BLS)[3] and not M[BLS]["cred"]   # 수급률은 SMR에서만 credible(보충 Table S3)
assert N["hot_top"][0][0] == "경상남도함안군" and N["cold_top"][0][0] == "충청남도금산군"
_Q = N["Q"]; _bus = _Q[_Q.index.str.startswith("부산")]; assert _bus.smr.median() < 1.0 + 0.05, _bus.smr.median()   # 고찰 '부산 사망 수준은 높지 않음'

if __name__ == "__main__":
    import re
    for h, t in METHODS + RESULTS: print("##", h, "\n", t, "\n")
    print("words M", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in METHODS), "R", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in RESULTS))
    print("busan smr", _bus.smr.describe().round(3).to_dict())
